#!/usr/bin/env bash
# nvidia/cluster-readiness-engine v0.6.0 - base variant: default
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/nvidia-cluster-readiness-engine-v0-6-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the default base variant into ./nvidia-cluster-readiness-engine-v0-6-0-default"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/nvidia-cluster-readiness-engine:v0.6.0@sha256:6a1a75b2d243ee4bd2cbea79a91052dfb36beb3e0bc4da0a03b2b589a4dab501 --base default --work-dir ./nvidia-cluster-readiness-engine-v0-6-0-default --non-interactive --namespace nvcre

say "Read what was rendered; nothing has touched the cluster yet"
ls ./nvidia-cluster-readiness-engine-v0-6-0-default/out/manifests

wait_for_crd() {
  crd_name="$1"
  deadline=$(( $(date +%s) + 180 ))
  until kubectl get "crd/${crd_name}" >/dev/null 2>&1; do
    if [ "$(date +%s)" -ge "$deadline" ]; then
      printf "CRD %s did not appear within 180 seconds.\n" "$crd_name" >&2
      return 1
    fi
    sleep 2
  done
  kubectl wait --for=condition=Established --timeout=120s "crd/${crd_name}"
}

say "Ensure the nvcre namespace exists"
kubectl create namespace nvcre --dry-run=client -o yaml | kubectl apply -f -

say "Check 8 CRDs included with this package"
missing_crds=0
if ! kubectl get crd/bandwidthmeasurements.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/certifications.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/goodputmeasurements.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/jobs.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/logprofiles.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/workflows.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/workloadruns.nvcre.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/servicemonitors.monitoring.coreos.com >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  kubectl apply --server-side -f ./nvidia-cluster-readiness-engine-v0-6-0-default/package/prerequisites/target-facts/default-crds.yaml
else
  say "The required CRDs already exist; leave them under their current owner"
fi
wait_for_crd bandwidthmeasurements.nvcre.nvidia.com
wait_for_crd certifications.nvcre.nvidia.com
wait_for_crd goodputmeasurements.nvcre.nvidia.com
wait_for_crd jobs.nvcre.nvidia.com
wait_for_crd logprofiles.nvcre.nvidia.com
wait_for_crd workflows.nvcre.nvidia.com
wait_for_crd workloadruns.nvcre.nvidia.com
wait_for_crd servicemonitors.monitoring.coreos.com

if [ -d ./nvidia-cluster-readiness-engine-v0-6-0-default/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./nvidia-cluster-readiness-engine-v0-6-0-default/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./nvidia-cluster-readiness-engine-v0-6-0-default/out/manifests

say "Done. The cluster received exactly the files in ./nvidia-cluster-readiness-engine-v0-6-0-default/out."
